// เตรียมพารามิเตอร์สำหรับ bodygraph API
const form = $('รับข้อมูลลูกค้า').first().json;
const loc = $input.first().json;
const list = Array.isArray(loc) ? loc : (loc.data || loc.results || []);
const tz = (list[0] && list[0].timezone) ? list[0].timezone : 'Asia/Bangkok';
const placeName = (list[0] && list[0].value) ? list[0].value : form['เมืองเกิด'];

// วันเกิดจากฟอร์ม (YYYY-MM-DD) + เวลา HH:MM
let date = String(form['วันเกิด']).slice(0,10);
let time = String(form['เวลาเกิด (24 ชม. เช่น 21:08)'] || '12:00').trim().replace('.',':');
if (/^\d{1,2}:\d{2}$/.test(time) === false) time = '12:00';
if (time.length === 4) time = '0' + time;

return [{ json: {
  name: form['ชื่อ'],
  email: form['อีเมล'],
  birthDate: date,
  birthTime: time,
  birthPlace: placeName,
  timezone: tz,
  dateParam: `${date} ${time}`,
  designName: 'lifeway'   // <-- ชื่อ Chart Design ใน dashboard bodygraph.com ต้องตรงเป๊ะ
}}];

// แยกข้อมูลชาร์ทจาก bodygraph API ให้กะทัดรัดพอส่งให้ Claude
const meta = $('เตรียมพารามิเตอร์').first().json;
const r = $input.first().json;
const P = r.Properties || {};
const nameOf = (o) => (o && (o.option || o.id || o.name)) || '';
const planets = ['Sun','Earth','North Node','South Node','Moon','Mercury','Venus','Mars','Jupiter','Saturn','Uranus','Neptune','Pluto'];
const act = (side) => { const out = {}; planets.forEach(p => { const v = (r[side]||{})[p]; if (v) out[p] = `${v.Gate}.${v.Line}`; }); return out; };

// หา SVG ไม่ว่า key จะเป็น SVG / svg / Svg
const svgKey = Object.keys(r).find(k => k.toLowerCase() === 'svg');
const svg = svgKey ? r[svgKey] : '';

const chart = {
  type: nameOf(P.Type),
  strategy: nameOf(P.Strategy),
  authority: nameOf(P.InnerAuthority),
  profile: nameOf(P.Profile),
  definition: nameOf(P.Definition),
  incarnationCross: nameOf(P.IncarnationCross),
  signature: nameOf(P.Signature),
  notSelfTheme: nameOf(P.NotSelfTheme),
  definedCenters: r.DefinedCenters || [],
  openCenters: r.OpenCenters || [],
  channels: r.Channels || [],
  gates: Object.values(r.Gates || {}),
  personality: act('Personality'),
  design: act('Design'),
  birthYear: Number(meta.birthDate.slice(0,4)),
};

return [{ json: { ...meta, chart, chartJson: JSON.stringify(chart), svg } }];

// สร้างรายการ 14 บท (1 item = 1 บท) แต่ละ item พกข้อมูลชาร์ทไปด้วย
const base = $input.first().json;
const chapters = [{"index": 1, "title": "คุณคือใคร: ภาพรวมของชาร์ทนี้", "instructions": "เปิดด้วยย่อหน้า \"คุณคือใครใน 10 บรรทัด\" ที่สังเคราะห์ Type, Authority, Profile, Definition, ศูนย์ที่ defined/open, channels และ Incarnation Cross ของชาร์ทนี้ให้เห็นภาพคนคนหนึ่ง จากนั้นอธิบายว่า Human Design คืออะไร (กำเนิด 1987 สังเคราะห์โหราศาสตร์ อี้จิง คับบาลาห์ จักระ ให้มองเป็นเครื่องมือสำรวจตัวเอง ไม่ใช่วิทยาศาสตร์หรือการทำนาย) วิธีอ่าน bodygraph (ศูนย์ ช่อง gate สีดำ/แดง) ความหมายของ Personality กับ Design แล้วพาเดินดูข้อเท็จจริงหลักของชาร์ทนี้ทีละอย่าง ปิดด้วยวิธีใช้เล่มนี้ (อ่านตามลำดับ ทดลอง 30 วัน ไม่มีอะไรเป็นคำตัดสิน)"}, {"index": 2, "title": "Type และ Strategy ของคุณ", "instructions": "อธิบาย Type ของชาร์ทนี้อย่างละเอียด: กลไกในชาร์ท (ศูนย์และช่องไหนที่ทำให้เป็น Type นี้ ไล่เส้นทางพลังงานให้เห็น) ออร่าที่คนรอบข้างรู้สึก Strategy ที่ถูกต้องพร้อมสคริปต์ประโยคใช้จริงในที่ทำงาน ครอบครัว และคู่ Signature กับ Not-self theme สัญญาณว่าใช้ชีวิตขัดกับ design ลักษณะพลังงาน (ต่อเนื่องหรือเป็นระลอก ตามว่า Sacral defined หรือไม่) การพักที่เหมาะกับ Type นี้ และ conditioning ในวัยเด็กที่ Type นี้มักเจอพร้อมวิธีถอด"}, {"index": 3, "title": "Authority: วิธีตัดสินใจที่เชื่อถือได้ของคุณ", "instructions": "อธิบาย Inner Authority ของชาร์ทนี้: กลไกทางร่างกาย ความแตกต่างจากการตัดสินใจด้วยสมอง สิ่งที่ \"การรอ\" หรือ \"การฟัง\" หมายถึงในทางปฏิบัติ ความตึงระหว่าง Authority กับ Type ของชาร์ทนี้และวิธีให้เกียรติทั้งสองอย่าง gates ที่เปิดอยู่ในศูนย์ที่เป็น Authority (รวม hanging gates) ว่ามีผลต่อการตัดสินใจอย่างไร พิธีกรรมตัดสินใจที่ใช้ได้จริง และผลเสียเมื่อตัดสินใจผิดวิธี (ยกฉากเรื่องงาน เงิน ความสัมพันธ์)"}, {"index": 4, "title": "Profile: บทบาทที่คุณเล่นในชีวิต", "instructions": "อธิบาย Profile ของชาร์ทนี้ทีละ line: ความหมายของ line แรก (จิตสำนึก) และ line ที่สอง (กาย/ไร้สำนึก) ว่าทำงานร่วมกันยังไง ปรากฏในงาน ความสัมพันธ์ ชื่อเสียง และวิธีที่คนอื่นมองคุณ กับดักของ Profile นี้ และยุทธศาสตร์ใช้ชีวิตให้ตรง Profile โยงกับ Type และ Authority ของชาร์ทนี้ว่าเมื่อรวมกันแล้วมีจุดแข็งและจุดเสี่ยงตรงไหน"}, {"index": 5, "title": "ศูนย์ที่มั่นคงในตัวคุณ", "instructions": "อธิบาย Definition ของชาร์ทนี้ (Single/Split/Triple/Quad) ว่าหมายถึงอะไรในชีวิตจริง จากนั้นอธิบายศูนย์ที่ defined ทีละศูนย์ตามที่มีจริงในชาร์ท: หน้าที่ของศูนย์ gates ที่เปิดอยู่ในศูนย์นั้นและความหมาย สิ่งที่ศูนย์นี้ให้คุณอย่างสม่ำเสมอ ปรากฏในชีวิตยังไง และจุดที่มันทำให้คุณสะดุด (ถ้าชาร์ทไม่มีศูนย์ defined เลย ให้อธิบายความหมายของ Reflector แทน)"}, {"index": 6, "title": "ศูนย์ที่เปิด: ที่ที่คุณรับโลกเข้ามา", "instructions": "อธิบายแนวคิดศูนย์เปิด (ขยายพลังของคนอื่น เป็นที่รับ conditioning และเป็นแหล่งปัญญาตลอดชีวิต) แล้วอธิบายศูนย์ที่ open ทีละศูนย์ตามที่มีจริงในชาร์ท พร้อมคำถาม Not-self ของแต่ละศูนย์ hanging gates ที่อยู่ในศูนย์เปิดและความหมาย ความเสี่ยงเฉพาะของชุดศูนย์เปิดในชาร์ทนี้ (เช่น ถ้า Sacral และ Root เปิดทั้งคู่ เสี่ยง burnout จากการเลียนแบบความอึดของคนอื่น) และโปรโตคอลปฏิบัติจริง"}, {"index": 7, "title": "ช่องทางพลังของคุณ", "instructions": "อธิบาย channels ที่ defined ทุกช่องในชาร์ทนี้ทีละช่อง: ชื่อช่อง วงจร (individual/tribal/collective/integration) ความหมายเชิงลึก ปรากฏในชีวิตยังไง ของขวัญและกับดัก แล้วปิดด้วยการสังเคราะห์ว่าช่องทั้งหมดรวมกันบรรยายคนคนหนึ่งอย่างไร (ถ้าชาร์ทไม่มี channel เลย ให้อธิบาย hanging gates ที่สำคัญที่สุด 4-5 gate แทน)"}, {"index": 8, "title": "ประตูที่กำหนดเรื่องราวของคุณ: Sun, Earth, Moon และ Nodes", "instructions": "อธิบาย Personality Sun และ Earth, Design Sun และ Earth (gate และ line) ว่าเป็นธีมหลักของบุคลิกและร่างกาย Moon ทั้งสองฝั่ง และ North/South Node ทั้งสองฝั่ง โดยอธิบาย Nodes ว่าเป็นสภาพแวดล้อมชีวิตที่เปลี่ยนราวอายุ 38-42 จากธีม South Node สู่ North Node (คำนวณช่วงปีจากปีเกิดในข้อมูล) อธิบายแต่ละ gate/line เป็นภาษาคนพร้อมฉากชีวิต รักษาความหมายตามอี้จิง/HD ให้ถูกต้อง ปิดด้วยย่อหน้าสั้นเรื่องดาวที่เหลือในฐานะตัวประกอบ"}, {"index": 9, "title": "Incarnation Cross: ธีมชีวิตของคุณ", "instructions": "อธิบายว่า Incarnation Cross คืออะไร (4 gates ของ Sun/Earth ทั้งสองฝั่ง ราว 70% ของพลังชาร์ท เป็นธีมชีวิตไม่ใช่คำบรรยายอาชีพ) ความหมายของมุม Right Angle / Juxtaposition / Left Angle ที่ชาร์ทนี้เป็น อธิบายชื่อ cross และ gates ทั้งสี่ว่าประกอบเป็นธีมเดียวกันอย่างไร ธีมนี้คลี่คลายตามช่วงชีวิตอย่างไรเมื่อผสมกับ Profile และ Type ของชาร์ทนี้ กับดักของ cross นี้ และวิธีใช้ชีวิตตามธีมนี้แบบรายสัปดาห์"}, {"index": 10, "title": "งานและอาชีพ: ตำแหน่งที่พลังของคุณทำงานได้เต็มที่", "instructions": "สังเคราะห์ทั้งชาร์ทเป็นคำแนะนำอาชีพ: Type (ควรเริ่ม/ตอบสนอง/รอคำเชิญ/สะท้อน), Authority (จังหวะรับงาน ลาออก เซ็นสัญญา), Profile, channels และ gates เด่น, ศูนย์เปิด (งานที่ดูดพลัง) ให้ role archetypes ที่เหมาะและที่ควรเลี่ยงอย่างเป็นรูปธรรม มีชุดประโยคที่ควรใช้ในที่ทำงานตาม Strategy ของชาร์ทนี้ และรายการสัญญาณว่าอยู่ผิดที่"}, {"index": 11, "title": "เงินและธุรกิจ: จังหวะของการให้และการได้รับ", "instructions": "มองเรื่องเงินผ่านชาร์ทนี้: ศูนย์ Heart (defined หรือ open) กับเรื่องคุณค่าและคำสัญญา, ศูนย์ Solar Plexus/Sacral/Spleen กับการตัดสินใจเรื่องเงิน, Type กับการเริ่มธุรกิจ, Profile กับการลองผิดลองถูก, channels/gates ที่เกี่ยวกับทรัพยากร ข้อตกลง ความทะเยอทะยาน โฟกัส ให้กฎเงินที่ใช้ได้จริงสำหรับชาร์ทนี้ (เช่น กฎรอกี่วันก่อนใช้จ่ายก้อนใหญ่ การเขียนข้อตกลง) พูดเป็นหลักการ ไม่ให้คำแนะนำการลงทุนเฉพาะเจาะจง"}, {"index": 12, "title": "ความสัมพันธ์: รักในแบบที่ออกแบบมา", "instructions": "ความสัมพันธ์ผ่านชาร์ทนี้: ออร่าของ Type ในความรัก, Authority กับการตัดสินใจเรื่องคู่ (ผูกมัด เลิก คุยเรื่องใหญ่), channels และ gates ที่เกี่ยวกับความใกล้ชิด ครอบครัว ข้อตกลง ความต้องการพื้นที่ส่วนตัว, ศูนย์เปิดที่ทำให้ยึดติดหรือเลียนแบบคู่, Profile กับรูปแบบการเรียนรู้ความสัมพันธ์ แนะนำว่าคู่แต่ละ Type (Generator, Projector, Manifestor, Reflector) จะสัมผัสคุณอย่างไร คำแนะนำเรื่องการเลี้ยงลูก/ครอบครัว และมิตรภาพ พร้อมประโยคที่ช่วยได้"}, {"index": 13, "title": "สุขภาพ พลังงาน และศิลปะของการพัก", "instructions": "การจัดการพลังงานตามชาร์ทนี้: ลักษณะพลังงานจาก Sacral และ Root (defined/open), การนอนตามคำแนะนำ HD สำหรับศูนย์เปิด, ศูนย์ Spleen กับภูมิคุ้มกันและการปล่อยวาง, ศูนย์ Solar Plexus กับร่างกาย, Heart กับการบังคับตัวเอง, gates ที่เกี่ยวกับร่างกายและจังหวะ ให้ template พลังงานรายสัปดาห์ที่เป็นรูปธรรม ใช้ภาษาระวัง และระบุครั้งเดียวว่านี่ไม่ใช่คำแนะนำทางการแพทย์ อาการต่อเนื่องควรพบแพทย์"}, {"index": 14, "title": "แผน 30 วัน: ทดลองใช้ชีวิตตาม Design ของคุณ", "instructions": "แผนทดลอง 30 วันแบ่ง 4 สัปดาห์ตามชาร์ทนี้: สัปดาห์ 1 ฝึก Strategy, สัปดาห์ 2 ฝึก Authority, สัปดาห์ 3 จัดการพลังงาน/ศูนย์เปิด, สัปดาห์ 4 ธีม Incarnation Cross และขอบเขตในความสัมพันธ์ แต่ละสัปดาห์มีการปฏิบัติรายวัน สิ่งที่ต้องสังเกต และคำถามบันทึกสั้นๆ จากนั้นมีหัวข้อ ## สิ่งที่อยากให้คุณจำไว้ เป็นบทปิดอบอุ่นประมาณ 300 คำที่สังเคราะห์ทั้งชาร์ท และย้ำว่านี่คือแผนที่สำหรับทดลอง ไม่ใช่คำตัดสิน ก่อนคำถาม 3 ข้อท้ายบท"}];
